import{_ as e,a,c as r,ac as d}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"易经：后世易学与术数分界","description":"梳理经学、义理、象数、八宫纳甲、梅花、丹道及现代类比的关系，说明不同体系的术语与证据不能混用。","frontmatter":{"title":"易经：后世易学与术数分界","description":"梳理经学、义理、象数、八宫纳甲、梅花、丹道及现代类比的关系，说明不同体系的术语与证据不能混用。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"易经专题","summary":"梳理经学、义理、象数、八宫纳甲、梅花、丹道及现代类比的关系，说明不同体系的术语与证据不能混用。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"怎样理解古代筮法：蓍草、钱币、动爻与解释边界","link":"/life/personal/yijing/divination"},"next":{"text":"把《周易》读进具体问题：乾坤、泰否、既济未济对读","link":"/life/personal/yijing/reading-practice"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"怎样理解古代筮法：蓍草、钱币、动爻与解释边界","link":"/life/personal/yijing/divination"},"next":{"text":"把《周易》读进具体问题：乾坤、泰否、既济未济对读","link":"/life/personal/yijing/reading-practice"}},"headers":[],"relativePath":"life/personal/yijing/traditions.md","filePath":"life/personal/yijing/traditions.md"}'),i={name:"life/personal/yijing/traditions.md"};function n(o,t,l,s,h,p){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="易经-后世易学与术数分界" tabindex="-1">易经：后世易学与术数分界 <a class="header-anchor" href="#易经-后世易学与术数分界" aria-label="Permalink to &quot;易经：后世易学与术数分界&quot;">​</a></h1><p>学习资料常把经传、六爻纳甲、梅花易数、命理、风水和养生全部叫作“易经”。这种说法反映了《易》在传统文化中的影响，也容易把不同的著作、方法和时代混成一门学问。本篇提供领域地图，帮助继续阅读时找到正确的书与问题。</p><h2 id="先看研究对象" tabindex="-1">先看研究对象 <a class="header-anchor" href="#先看研究对象" aria-label="Permalink to &quot;先看研究对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路向</th><th>主要研究什么</th><th>常用材料或工具</th><th>不应混同</th></tr></thead><tbody><tr><td>经文训诂与版本</td><td>字词、异文、断句、篇章和古代语境</td><td>经文、注疏、出土文本、校勘材料</td><td>不能只凭当代励志含义决定古字本义</td></tr><tr><td>义理易学</td><td>时位、德行、处境、行动与天地之道</td><td>经传、王弼、程颐等注释</td><td>不是取消卦象和原文，随意谈人生</td></tr><tr><td>象数易学</td><td>卦画、数位、取象、卦变及其对应</td><td>汉易材料、宋代图学、各家象数体系</td><td>不同派别没有一份完全一致的总表</td></tr><tr><td>筮占传统</td><td>起卦、动静、占辞选取与解释</td><td>蓍法、钱法、占例</td><td>起卦算得正确，不等于预测已验证</td></tr><tr><td>纳甲与八宫</td><td>干支五行、世应、六亲、旺衰等规则</td><td>《京氏易传》及后续术数著作</td><td>不等于逐句解释《周易》卦爻辞</td></tr><tr><td>梅花类方法</td><td>数、象、体用、互变、外应的组合</td><td>传世《梅花易数》等</td><td>不能直接替换大衍筮法的步骤和概率</td></tr><tr><td>其他借易著作</td><td>借卦象说明丹道、医理、空间或其他体系</td><td>各领域专门文献</td><td>同用阴阳五行词汇不代表理论完全相同</td></tr></tbody></table><p>这张表是阅读分类，不是给流派排高低。历代作者也可能同时采用多个取向，不能把“义理”和“象数”想成从未交流的两座孤岛。</p><h2 id="八宫-换一种组织六十四卦的方法" tabindex="-1">八宫：换一种组织六十四卦的方法 <a class="header-anchor" href="#八宫-换一种组织六十四卦的方法" aria-label="Permalink to &quot;八宫：换一种组织六十四卦的方法&quot;">​</a></h2><p>传世《京氏易传》以八卦分宫，讨论世应、飞伏、游魂和归魂等。四库本提要还特别指出：书名虽称“易传”，它与直接诠释经文的注疏不同；这也是古代目录学已经做出的区分，不是今天才产生的问题。<a href="https://zh.wikisource.org/wiki/%E4%BA%AC%E6%B0%8F%E6%98%93%E5%82%B3_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%85%A8%E8%A6%BD" target="_blank" rel="noopener noreferrer">《京氏易传》四库本提要及正文</a>。</p><p>以常见乾宫序列为例：</p><table tabindex="0"><thead><tr><th>顺序</th><th>卦名</th><th>常见名称</th></tr></thead><tbody><tr><td>1</td><td>乾</td><td>本宫纯卦</td></tr><tr><td>2</td><td>姤</td><td>一世</td></tr><tr><td>3</td><td>遯</td><td>二世</td></tr><tr><td>4</td><td>否</td><td>三世</td></tr><tr><td>5</td><td>观</td><td>四世</td></tr><tr><td>6</td><td>剥</td><td>五世</td></tr><tr><td>7</td><td>晋</td><td>游魂</td></tr><tr><td>8</td><td>大有</td><td>归魂</td></tr></tbody></table><p>这一序列也见于<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%9C%AC%E7%BE%A9_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%85%A8%E8%A6%BD" target="_blank" rel="noopener noreferrer">《周易本义》所附分宫卦象次序</a>。它不是《周易》从第 1 卦到第 8 卦的篇次；通行前八卦是乾、坤、屯、蒙、需、讼、师、比。</p><h3 id="几个需要另学的术语" tabindex="-1">几个需要另学的术语 <a class="header-anchor" href="#几个需要另学的术语" aria-label="Permalink to &quot;几个需要另学的术语&quot;">​</a></h3><ul><li><strong>纳甲</strong>：把天干等系统与卦象相配的传统方法；具体配法要落实到书和派别。</li><li><strong>世与应</strong>：八宫体系用以定位关系的爻位概念，不可直接等同经传解释的一四、二五、三上之“应”。</li><li><strong>六亲</strong>：以后世术数的五行生克关系命名父母、兄弟、子孙、妻财、官鬼等类别。“亲”在这里有术语意义，不是逐字对应现实家属名单。</li><li><strong>飞伏、游魂、归魂</strong>：特定变化关系或位置术语；不能只按现代字面理解成鬼魂叙事。</li></ul><p>在《京氏易传》乾卦条中，已经能看到甲壬、六位、五行、世应等词同处一套说明。要读懂它，需要独立掌握这套体系，而不是只认识乾卦六条爻辞即可。</p><h2 id="十二消息卦与季节对应" tabindex="-1">十二消息卦与季节对应 <a class="header-anchor" href="#十二消息卦与季节对应" aria-label="Permalink to &quot;十二消息卦与季节对应&quot;">​</a></h2><p>后世常以复、临、泰、大壮、夬、乾，接姤、遯、否、观、剥、坤，表现阳的增长与消退。可以把每卦由下起阳爻逐渐增多、再由阴爻逐渐增多的结构画出来，观察六位组合如何循环。</p><p>月份配属属于特定的历法与易学解释，不应不说明历法、月建和传统就直接对应今天的公历日期。《京氏易传》乾、姤、遯等条已有节候、月建与消长的说明，读时宜保留其历史语境。<a href="https://zh.wikisource.org/wiki/%E4%BA%AC%E6%B0%8F%E6%98%93%E5%82%B3_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%85%A8%E8%A6%BD" target="_blank" rel="noopener noreferrer">原文</a>。</p><h2 id="梅花易数-数、象与体用" tabindex="-1">梅花易数：数、象与体用 <a class="header-anchor" href="#梅花易数-数、象与体用" aria-label="Permalink to &quot;梅花易数：数、象与体用&quot;">​</a></h2><p>传世<a href="https://zh.wikisource.org/wiki/%E6%A2%85%E8%8A%B1%E6%98%93%E6%95%B8" target="_blank" rel="noopener noreferrer">《梅花易数》目录</a>包括年月日時起卦、物数、声音、字占、体用生克、互变等内容。由此能看出它与先准备五十策、反复揲蓍的大衍方法不同。它还用“先天”“后天”描述某些起卦路径，这些用法不能直接等同<a href="./diagrams">八卦方位图</a>的全部含义。</p><p>该书常题邵雍，相关序言和故事包含很强的传说色彩。现存传本的作者题署与历史上的实际写作、编纂过程，应当分别查证；本篇只说明传本里有哪些方法，不依据序言故事证明预测确实发生过。</p><p>“体”“用”是这套解释中特定的区分，“互”“变”也参与判断。同一次材料若一会儿用梅花的体用，一会儿改用纳甲的世应，再选择最合心意的爻辞，就已经更换了规则。比较方法之前，先记录每套方法独立怎样得出结论。</p><h2 id="丹道、医易、风水与命理" tabindex="-1">丹道、医易、风水与命理 <a class="header-anchor" href="#丹道、医易、风水与命理" aria-label="Permalink to &quot;丹道、医易、风水与命理&quot;">​</a></h2><p><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E5%8F%83%E5%90%8C%E5%A5%91" target="_blank" rel="noopener noreferrer">《周易参同契》</a>的篇目包括乾坤设位、日月悬象、水火情性、爻变功用等，展示易学语汇进入另一类著作后的组织方式。它不能因书名中有“周易”就当成六十四卦经文的续篇。</p><p>医易、风水、命理同样有各自的文献、对象与规则。本专题在这里交代关联和分界，不把卦象的身体对应写成治疗方法，也不把方位图写成建筑安全或个人命运的判断。若要研究其中一门，应另建该门的术语和书目，再辨认它引用《易》的具体方式。</p><p>阴阳、五行、干支是多个传统共享的词汇，<strong>共享词汇不等于共享全部论证</strong>。例如《说卦》取身体象、某部医书论脏腑、某派术数谈六亲，可以互相影响，却不能凭名称相近就把三种结论当作互相验证。</p><h2 id="现代类比可以怎样使用" tabindex="-1">现代类比可以怎样使用 <a class="header-anchor" href="#现代类比可以怎样使用" aria-label="Permalink to &quot;现代类比可以怎样使用&quot;">​</a></h2><p>把既济的“思患而豫防之”用于提醒自己完成事情后仍要检查，是一种有文本触点的现代阅读。若进一步声称易经已预言某项工程会出故障，就需要完全不同的证据。类似地，把卦画编码为 0 和 1 有利于展示组合，不等于经书已经包含现代计算机技术。</p><p>可采用三栏笔记：第一栏原文，第二栏传统解释，第三栏今天的类比。类比的好坏应看它是否帮助提出清楚的问题、是否保留现实反例，以及是否愿意在证据不足时停止推断。</p><h2 id="继续深入的路线" tabindex="-1">继续深入的路线 <a class="header-anchor" href="#继续深入的路线" aria-label="Permalink to &quot;继续深入的路线&quot;">​</a></h2><p>先读完<a href="./text-history">经传结构</a>和<a href="./ten-wings">十翼</a>，再选一条方向：研究文字就对照注疏和版本；研究思想就读<a href="./commentaries">注家比较</a>；研究图学先识别<a href="./diagrams">图式</a>；研究占筮先固定<a href="./divination">操作方法</a>。每次只引入一套新规则，才能知道新的解释究竟来自哪里。</p><p><a href="./overview">返回易经专题</a></p>',30)])])}const f=e(i,[["render",n]]);export{g as __pageData,f as default};
